%% Pilot generation (for channel estimation and equalization)
bitsPilot    = bits(1 : nPilotSymbols * log2(M));
symbolsPilot = symbolMapping(bitsPilot, M, modScheme);
sPilot       = pulseShaping(symbolsPilot, sps);

%% Data generation (information we want to communicate)
bitsData    = bits(1 : nDataSymbols * log2(M));
symbolsData = symbolMapping(bitsData, M, modScheme);
sData       = pulseShaping(symbolsData, sps);

%% Frame integration
sFrame = [sPilot; sData];
sFrame = sFrame / max(max(real(sFrame)), max(imag(sFrame)));
sFrame = [sHeader / max(real(sHeader)); sFrame];

%% Converting the I/Q samples into a form the SG can understand
waveformFormatConversion(sFrame, sprintf("%d%s_%gSR", M, modScheme, Rs / 1e6));

%% Plots
% Data constellation
figure();
subplot(3, 2, [1; 3; 5]);
plot(symbolsData, "kx", LineWidth=2, MarkerSize=12);
axis("equal"); xlim([-1.5, 1.5]); ylim([-1.5, 1.5]);
xlabel("I"); ylabel("Q");
set(gca, XAxisLocation="origin", YAxisLocation="origin", XTick=[], YTick=[]);
title("Constellation diagram");

% Frame in the time domain
