subplot(3, 2, 2);
plot(tFrame * 1e6, real(sFrame));
xlim([tFrame(1), tFrame(end)] * 1e6); ylim([-1, 1]);
ylabel("In-phase");
title("Frame in time domain");
subplot(3, 2, 4);
plot(tFrame * 1e6, imag(sFrame));
xlim([tFrame(1), tFrame(end)] * 1e6); ylim([-1, 1]);
ylabel("Quadrature");
xlabel("Time (us)");

% Frame in the frequency domain
[Px, f] = frequencyDomain(sFrame, Fs, "double");
subplot(3, 2, 6);
plot(f / 1e6, 10 * log10(Px));
xlim([f(1), f(end)] / 1e6);
xlabel("Frequency (MHz)"); ylabel("Power Spectrum (dB)");
title("Frame in the frequency domain");